nyms/?original=asmi\",\"children\":[\"$\",\"em\",null,{\"children\":\"asmi\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"I am\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-10\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-saṁvṛttaḥ\",{\"href\":\"/en/search/synonyms/?original=saṁvṛttaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"saṁvṛttaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"settled\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-11\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-sa\",{\"href\":\"/en/search/synonyms/?original=sa\",\"children\":[\"$\",\"em\",null,{\"children\":\"sa\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-cetāḥ\",{\"href\":\"/en/search/synonyms/?original=cetāḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"cetāḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"in my consciousness\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-12\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-prakṛtim\",{\"href\":\"/en/search/synonyms/?original=prakṛtim\",\"children\":[\"$\",\"em\",null,{\"children\":\"prakṛtim\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"to my own nature\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-13\",{\"className\":\"inline\",\"children\":[[\"$L31\"],\" — \",\"$L32\",\".\"]}]]}]}]]]}]\n"])self.__next_f.push([1,"2d:[\"$\",\"div\",\"3420-translation,3420-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L29\",\"child-3424\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"When Arjuna thus saw Kṛṣṇa in His original form, he said: O Janārdana, seeing this humanlike form, so very beautiful, I am now composed in mind, and I am restored to my original nature.\"}}]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"3420-purport,3420-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L29\",\"child-3425\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Here the words mānuṣaṁ rūpam clearly indicate the Supreme Personality of Godhead to be originally two-handed. Those who deride Kṛṣṇa as if He were an ordinary person are shown here to be ignorant of His divine nature. If Kṛṣṇa is like an ordinary human being, then how is it possible for Him to show the universal form and again to show the four-handed Nārāyaṇa form? So it is very clearly stated in Bhagavad-gītā that one who thinks that Kṛṣṇa is an ordinary person and who misguides the reader by claiming that it is the impersonal Brahman within Kṛṣṇa speaking is doing the greatest injustice. Kṛṣṇa has actually shown His universal form and His four-handed Viṣṇu form. So how can He be an ordinary human being? A pure devotee is not confused by misguiding commentaries on Bhagavad-gītā because he knows what is what. The original verses of Bhagavad-gītā are as clear as the sun; they do not require lamplight from foolish commentators.\"}}]}]]]}]\n"])self.__next_f.push([1,"33:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleana