सुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम ।
देवा अप्यस्य रूपस्य नित्यं दर्शनकाङ्‍‍क्षिण: ॥ ५२ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3428,\"bb\":3017,\"url_path\":\"/en/library/bg/11/52/b3017/\",\"body_value\":\"śrī-bhagavān uvāca
su-durdarśam idaṁ rūpaṁ
dṛṣṭavān asi yan mama
devā apy asya rūpasya
nityaṁ darśana-kāṅkṣiṇaḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3429,\"bb\":3018,\"url_path\":\"/en/library/bg/11/52/b3018/\",\"shadow_value\":\"śrī-bhagavān uvāca – the Supreme Personality of Godhead said; su-durdarśam – very difficult to see; idam – this; rūpam – form; dṛṣṭavān asi – as you have seen; yat – which; mama – of Mine; devāḥ – the demigods; api – also; asya – this; rūpasya – form; nityam – eternally; darśana-kāṅkṣiṇaḥ – aspiring to see.\",\"word_for_word_value\":[{\"word\":\"śrī-bhagavān uvāca\",\"translation\":\"the Supreme Personality of Godhead said\"},{\"word\":\"su-durdarśam\",\"translation\":\"very difficult to see\"},{\"word\":\"idam\",\"translation\":\"this\"},{\"word\":\"rūpam\",\"translation\":\"form\"},{\"word\":\"dṛṣṭavān asi\",\"translation\":\"as you have seen\"},{\"word\":\"yat\",\"translation\":\"which\"},{\"word\":\"mama\",\"translation\":\"of Mine\"},{\"word\":\"devāḥ\",\"translation\":\"the demigods\"},{\"word\":\"api\",\"translation\":\"also\"},{\"word\":\"asya\",\"translation\":\"this\"},{\"word\":\"rūpasya\",\"translation\":\"form\"},{\"word\":\"nityam\",\"translation\":\"eternally\"},{\"word\":\"darśana-kāṅkṣiṇaḥ\",\"translation\":\"aspiring to see\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3430,\"bb\":3019,\"url_path\":\"/en/library/bg/11/52/b3019/\",\"body_value\":\"The Supreme Personality of Godhead said: My dear Arjuna, this form of Mine you are now seeing is very difficult to behold. Even the demigods are ever seeking the opportunity to see this form, which is so dear.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3431,\"bb\":3020,\"url_path\":\"/en/library/bg/11/52/b3020/\",\"body_value\":\"$25\"},{\"type\":